// Helper function for multisets equality on Vec<i8>  
fn multiset_equal(v1: &Vec<i8>, v2: &Vec<i8>) -> bool {
    // same length
    if v1.len() != v2.len() {
        return false;
    }
    // for all elements in v1, the count in v1 equals count in v2
    forall(|x: i8| count_elem(v1, x) == count_elem(v2, x))
}

// Count occurrences of element x in vector v
fn count_elem(v: &Vec<i8>, x: i8) -> usize {
    let mut count = 0;
    let mut idx = 0;
    while idx < v.len() {
        if v[idx] == x {
            count += 1;
        }
        idx += 1;
    }
    count
}